const config = {
  "previewFeatures": [
    "driverAdapters"
  ],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// =============================================================\n// JKA Bangladesh — Prisma Schema (3NF, role-normalized)\n// PostgreSQL via Supabase · Prisma 7 · driverAdapters preview\n//\n// Identity is split across:\n//   users               — shared profile (mirrors auth.users)\n//   roles               — RBAC role catalog (PK = slug)\n//   permissions         — permission catalog\n//   role_permissions    — M2M role↔permission\n//   students            — student-specific profile (1:1 with users)\n//   instructors         — instructor-specific profile (1:1 with users)\n//   dojo_managers       — dojo manager profile  (1:1 with users)\n//   dojo_owners         — dojo owner profile    (1:1 with users)\n//   admins              — admin profile         (1:1 with users)\n//\n// Each role-specific table has id = users.id (PK + FK). A user has\n// exactly one row in `users` and one row in the matching role table.\n//\n// Naming convention:\n//   - Prisma fields  → camelCase  (TypeScript client)\n//   - DB columns     → snake_case (via @map)\n//   - DB tables      → snake_case (via @@map)\n// =============================================================\n\ngenerator client {\n  provider        = \"prisma-client-js\"\n  output          = \"../prisma/generated/client\"\n  previewFeatures = [\"driverAdapters\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─────────────────────────────────────────────\n// ENUMS\n// ─────────────────────────────────────────────\n\nenum MembershipStatus {\n  PENDING // Registered but has not paid\n  ACTIVE // Paid and active member\n  EXPIRED // Membership lapsed\n  SUSPENDED // Admin-suspended\n}\n\n// Multi-step joining flow for new students. Independent of MembershipStatus\n// (which tracks whether the annual JKA fee is currently in good standing).\nenum JoinStage {\n  FEE_UNPAID // Step 1: pay JKA membership fee\n  AWAITING_APPROVAL // Step 2: dojo owner accepts + confirms rank\n  PAST_BELT_UNPAID // Step 3: pay for previous belts (non-white only)\n  JOINED // Step 4: complete — full portal access\n}\n\nenum GradingResult {\n  PASSED\n  FAILED\n  ABSENT\n}\n\n// Post-publish pipeline stage for a PASSED grading. Non-passed rows stay at\n// QUALIFIED but never advance — only passes reach the manager/dojo-head steps.\nenum GradingPipelineStage {\n  QUALIFIED // Passed & published — awaits Manager background/dues verification\n  VERIFIED // Manager verified — awaits Dojo Head submission to JKA HQ\n  SUBMITTED // Sent to federation — awaits certificate issuance\n}\n\nenum ApplicationStatus {\n  SUBMITTED\n  APPROVED\n  REJECTED\n  CANCELLED\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n}\n\n// Payment lifecycle for the transaction log.\nenum PaymentTransactionStatus {\n  PENDING // Order created, buyer redirected to gateway\n  SUCCESS // Gateway validated the payment\n  FAILED // Gateway rejected the payment\n  CANCELLED // Buyer cancelled before paying\n}\n\n// What the payment was for — lets admins group by revenue stream.\nenum PaymentTransactionKind {\n  MEMBERSHIP // First JKA membership fee or renewal\n  PAST_BELT_FEE // Catch-up fee during joining\n  CERTIFICATES // Batch of printed grading certificates\n  DOJO_RENEWAL // Federation membership for a dojo\n  TRANSFER // Student dojo transfer fee\n  SERVICE_REQUEST // Kyu/Dan conversion or other admin-added services\n  EVENT_TICKET // Event registration\n  SHOP // Shop merchandise\n  OTHER // Anything not otherwise classified\n}\n\n// Provider that handled the transaction.\nenum PaymentProvider {\n  SSLCOMMERZ\n  DEV_BYPASS\n  MANUAL\n}\n\nenum ShopFulfillmentStatus {\n  PREPARING\n  IN_TRANSIT\n  DELIVERED\n  RETURNED\n}\n\nenum NotificationType {\n  INFO\n  WARNING\n  SUCCESS\n  PAYMENT\n  GRADING\n  EVENT\n  RENEWAL\n  CERTIFICATE\n  TRANSFER\n  SERVICE\n}\n\nenum StudentTransferStatus {\n  PENDING_PAYMENT\n  AWAITING_DOJO\n  AWAITING_ADMIN\n  AWAITING_NEW_DOJO\n  APPROVED\n  DENIED\n  CANCELLED\n}\n\nenum StudentTransferDojoDecision {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n// Generic service-request workflow (currently used for Kyu/Dan Conversion\n// and any custom services the admin adds — Transfer Dojo has its own\n// dedicated request model above).\nenum ServiceRequestStatus {\n  PENDING_PAYMENT\n  AWAITING_DOJO\n  AWAITING_ADMIN\n  APPROVED\n  DENIED\n  CANCELLED\n}\n\nenum ServiceRequestDojoDecision {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum CertificateRequestStatus {\n  PENDING_PAYMENT\n  PAID\n  GENERATING\n  ISSUED\n  FAILED\n}\n\nenum EventCategory {\n  BELT_TEST\n  TOURNAMENT\n  SEMINAR\n  TRAINING_CAMP\n  OTHER\n}\n\nenum AttachmentType {\n  IMAGE\n  PDF\n}\n\n// Who is allowed to register for an event.\nenum EventParticipantType {\n  PUBLIC // anyone, including guests\n  STUDENTS // signed-in members with the STUDENT role\n  INSTRUCTORS // signed-in members with the INSTRUCTOR role\n  PARENTS // guardians of a registered student (child member number required)\n  DOJO_MEMBERS // signed-in members of the event's dojo\n\n  @@map(\"event_participant_type\")\n}\n\nenum AchievementTier {\n  COMMON\n  RARE\n  EPIC\n  LEGENDARY\n}\n\nenum AchievementRule {\n  MANUAL\n  ATTENDANCE_COUNT\n  CONSECUTIVE_ATTENDANCE\n  GRADINGS_PASSED\n  EVENTS_ATTENDED\n  TOURNAMENTS_PARTICIPATED\n  TOURNAMENT_WINS\n  CERTIFICATES_EARNED\n  HIGH_MARK_GRADINGS\n}\n\n// Tournament competition type — matches the two appendices in the JKA\n// tournament rulebook. Set on TournamentDetail when an Event's category is\n// TOURNAMENT.\nenum TournamentEventType {\n  KATA\n  KUMITE\n\n  @@map(\"tournament_event_type\")\n}\n\n// Binary sport-category gender for competition division matching. Independent\n// of any wider identity signal we may capture elsewhere.\nenum Gender {\n  MALE\n  FEMALE\n}\n\n// ─────────────────────────────────────────────\n// RBAC — Role / Permission / RolePermission\n// Role IDs are slugs (STUDENT, INSTRUCTOR, DOJO_MANAGER, DOJO_OWNER, ADMIN)\n// seeded by the SQL migration.\n// ─────────────────────────────────────────────\n\nmodel Role {\n  id            String  @id // slug\n  displayName   String  @map(\"display_name\")\n  displayNameBn String? @map(\"display_name_bn\")\n  description   String?\n\n  users           User[]\n  rolePermissions RolePermission[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  @@map(\"roles\")\n}\n\nmodel Permission {\n  id          String  @id // slug e.g. \"members.read.own_dojo\"\n  resource    String // \"members\" | \"gradings\" | ...\n  action      String // \"read\" | \"write\" | \"approve\" | ...\n  description String?\n\n  rolePermissions RolePermission[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  @@map(\"permissions\")\n}\n\nmodel RolePermission {\n  roleId       String @map(\"role_id\")\n  permissionId String @map(\"permission_id\")\n\n  role       Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  @@id([roleId, permissionId])\n  @@map(\"role_permissions\")\n}\n\n// ─────────────────────────────────────────────\n// USERS  (mirrors auth.users via id)\n// Shared profile fields for every authenticated user. Role-specific\n// data lives in the matching role table (students / instructors / etc).\n// ─────────────────────────────────────────────\n\nmodel User {\n  id                 String  @id @db.Uuid // = auth.users.id\n  // Supabase auth email. Real for admins (used for password reset); synthetic\n  // `{uuid}@members.jkabangladesh.com` for non-admins so a family can share\n  // one real email across many accounts. Always unique — Supabase requires it.\n  email              String  @unique\n  // Real contact email used for notifications. Optional and non-unique — a\n  // parent's inbox can appear on multiple children's accounts.\n  contactEmail       String? @map(\"contact_email\")\n  phone              String?\n  fullName           String  @map(\"full_name\")\n  avatarUrl          String? @map(\"avatar_url\")\n  bio                String?\n  roleId             String  @default(\"STUDENT\") @map(\"role_id\")\n  isActive           Boolean @default(true) @map(\"is_active\")\n  memberNumber       String? @unique @map(\"member_number\")\n  // Set when a Dojo Head creates the account with a temporary password —\n  // the portal layout redirects the user to /set-password until it clears.\n  mustChangePassword Boolean @default(false) @map(\"must_change_password\")\n\n  role        Role         @relation(fields: [roleId], references: [id])\n  profile     Profile?\n  student     Student?\n  instructor  Instructor?\n  dojoManager DojoManager?\n  dojoOwner   DojoOwner?\n  admin       Admin?\n\n  notifications             Notification[]\n  orders                    ShopOrder[]\n  eventRegistrations        EventRegistration[]\n  eventCheckIns             EventRegistration[]      @relation(\"EventCheckIns\")\n  eventsPosted              Event[]                  @relation(\"EventsPosted\")\n  announcementsPosted       Announcement[]           @relation(\"AnnouncementsPosted\")\n  dojoSalesAsBuyer          DojoSale[]               @relation(\"DojoSaleBuyer\")\n  dojoSalesSold             DojoSale[]               @relation(\"DojoSaleSeller\")\n  achievementsAwarded       StudentAchievement[]     @relation(\"StudentAchievementsAwarded\")\n  tournamentEntries         TournamentParticipant[]  @relation(\"TournamentEntries\")\n  transfersDojoActed        StudentTransferRequest[] @relation(\"TransferDojoActor\")\n  transfersAdminActed       StudentTransferRequest[] @relation(\"TransferAdminActor\")\n  transfersNewDojoActed     StudentTransferRequest[] @relation(\"TransferNewDojoActor\")\n  dojoHistoryChanges        StudentDojoHistory[]     @relation(\"HistoryChangedBy\")\n  paymentTransactions       PaymentTransaction[]     @relation(\"UserTransactions\")\n  dojoOwnerInvitesSent      DojoOwnerInvite[]        @relation(\"DojoOwnerInvites\")\n  serviceRequestsDojoActed  ServiceRequest[]         @relation(\"ServiceRequestDojoActor\")\n  serviceRequestsAdminActed ServiceRequest[]         @relation(\"ServiceRequestAdminActor\")\n  serviceCouponsCreated     ServiceCoupon[]          @relation(\"ServiceCouponCreator\")\n  divisionPresetsCreated    DivisionPreset[]         @relation(\"DivisionPresetsCreated\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([roleId])\n  @@map(\"users\")\n}\n\n// ─────────────────────────────────────────────\n// PROFILE  — shared personal details (1:1 with User)\n// ─────────────────────────────────────────────\n\nmodel Profile {\n  id                    String    @id @db.Uuid // = users.id\n  dateOfBirth           DateTime? @map(\"date_of_birth\") @db.Date\n  gender                Gender?\n  bloodGroup            String?   @map(\"blood_group\")\n  address               String?\n  nationalId            String?   @unique @map(\"national_id\")\n  fatherName            String?   @map(\"father_name\")\n  motherName            String?   @map(\"mother_name\")\n  emergencyContactName  String?   @map(\"emergency_contact_name\")\n  emergencyContactPhone String?   @map(\"emergency_contact_phone\")\n\n  user User @relation(fields: [id], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"profiles\")\n}\n\n// ─────────────────────────────────────────────\n// STUDENT  — student-specific profile (1:1 with User)\n// ─────────────────────────────────────────────\n\nmodel Student {\n  id          String    @id @db.Uuid // = users.id\n  currentRank String    @default(\"White Belt\") @map(\"current_rank\")\n  joinDate    DateTime  @default(now()) @map(\"join_date\") @db.Timestamptz(6)\n  expiryDate  DateTime? @map(\"expiry_date\") @db.Timestamptz(6)\n  dojoId      String?   @map(\"dojo_id\") @db.Uuid\n\n  onboardingComplete Boolean          @default(false) @map(\"onboarding_complete\")\n  membershipStatus   MembershipStatus @default(PENDING) @map(\"membership_status\")\n\n  // Multi-step joining flow — see JoinStage enum.\n  joinStage      JoinStage @default(FEE_UNPAID) @map(\"join_stage\")\n  requestedRank  String?   @map(\"requested_rank\") // Rank student picked at signup\n  assignedRank   String?   @map(\"assigned_rank\") // Rank the dojo owner confirmed on approval\n  pastBeltFeeBDT Int?      @map(\"past_belt_fee_bdt\") // Calculated at approval; null when white belt\n  joinPdfUrl     String?   @map(\"join_pdf_url\") // \"Bring this to your dojo\" printable doc\n  joinedAt       DateTime? @map(\"joined_at\") @db.Timestamptz(6)\n\n  user User  @relation(fields: [id], references: [id], onDelete: Cascade)\n  dojo Dojo? @relation(\"DojoStudents\", fields: [dojoId], references: [id])\n\n  gradings            Grading[]\n  gradingApplications GradingApplication[]\n  certificateRequests CertificateRequest[]\n  achievements        StudentAchievement[]     @relation(\"StudentAchievements\")\n  transferRequests    StudentTransferRequest[]\n  serviceRequests     ServiceRequest[]\n  dojoHistory         StudentDojoHistory[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([dojoId])\n  @@map(\"students\")\n}\n\n// ─────────────────────────────────────────────\n// INSTRUCTOR  — 1:1 with User\n// ─────────────────────────────────────────────\n\nmodel Instructor {\n  id         String   @id @db.Uuid // = users.id\n  dojoId     String?  @map(\"dojo_id\") @db.Uuid\n  joinedDate DateTime @default(now()) @map(\"joined_date\") @db.Timestamptz(6)\n  bio        String?\n\n  user User  @relation(fields: [id], references: [id], onDelete: Cascade)\n  dojo Dojo? @relation(\"DojoInstructors\", fields: [dojoId], references: [id])\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([dojoId])\n  @@map(\"instructors\")\n}\n\n// ─────────────────────────────────────────────\n// DOJO MANAGER  — 1:1 with User\n// ─────────────────────────────────────────────\n\nmodel DojoManager {\n  id     String  @id @db.Uuid // = users.id\n  dojoId String? @map(\"dojo_id\") @db.Uuid\n\n  user User  @relation(fields: [id], references: [id], onDelete: Cascade)\n  dojo Dojo? @relation(\"DojoManagers\", fields: [dojoId], references: [id])\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([dojoId])\n  @@map(\"dojo_managers\")\n}\n\n// ─────────────────────────────────────────────\n// DOJO OWNER  — 1:1 with User, 1:1 with Dojo\n// Replaces the partial unique index `members_one_owner_per_dojo` with\n// a hard UNIQUE constraint on dojo_id.\n// ─────────────────────────────────────────────\n\nmodel DojoOwner {\n  id           String  @id @db.Uuid // = users.id\n  dojoId       String? @unique @map(\"dojo_id\") @db.Uuid\n  signatureUrl String? @map(\"signature_url\")\n\n  user User  @relation(fields: [id], references: [id], onDelete: Cascade)\n  dojo Dojo? @relation(\"DojoOwner\", fields: [dojoId], references: [id])\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"dojo_owners\")\n}\n\n// ─────────────────────────────────────────────\n// ADMIN  — 1:1 with User\n// ─────────────────────────────────────────────\n\nmodel Admin {\n  id    String  @id @db.Uuid // = users.id\n  scope String? // optional admin scope tag\n\n  user User @relation(fields: [id], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"admins\")\n}\n\n// ─────────────────────────────────────────────\n// BELT RANKS\n// ─────────────────────────────────────────────\n\nmodel BeltRank {\n  id         String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name       String  @unique\n  kyuDan     String? @map(\"kyu_dan\")\n  colorHex   String? @map(\"color_hex\")\n  orderIndex Int     @unique @map(\"order_index\")\n\n  certificatePrice Decimal? @map(\"certificate_price\") @db.Decimal(10, 2)\n\n  gradingsFrom        Grading[]            @relation(\"GradingFromRank\")\n  gradingsTo          Grading[]            @relation(\"GradingToRank\")\n  gradingEvents       GradingEvent[]       @relation(\"EventTargetRank\")\n  gradingApplications GradingApplication[] @relation(\"AppTargetRank\")\n  minRankEvents       Event[]              @relation(\"EventMinRank\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"belt_ranks\")\n}\n\n// ─────────────────────────────────────────────\n// DOJOS\n// ─────────────────────────────────────────────\n\nmodel Dojo {\n  id        String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name      String\n  shortName String? @map(\"short_name\")\n  address   String?\n  city      String?\n  latitude  Float?\n  longitude Float?\n  phone     String?\n  email     String?\n  isActive  Boolean @default(true) @map(\"is_active\")\n\n  annualFee  Decimal?  @map(\"annual_fee\") @db.Decimal(10, 2)\n  expiryDate DateTime? @map(\"expiry_date\") @db.Timestamptz(6)\n\n  renewalOrders ShopOrder[] @relation(\"DojoRenewalOrders\")\n\n  certificateOrders   ShopOrder[]          @relation(\"DojoCertificateOrders\")\n  certificateRequests CertificateRequest[]\n\n  ownerSignatureUrl String? @map(\"owner_signature_url\")\n  logoUrl           String? @map(\"logo_url\")\n\n  // Feature keys the JKA admin has explicitly locked for this dojo. Union\n  // with the automatic milestone locks (dojos with <30 active students get\n  // certificates/announcements/transfers/invite-staff auto-locked).\n  // Values are from lib/dojo/feature-locks.ts FEATURE_KEYS.\n  lockedFeatures String[] @default([]) @map(\"locked_features\")\n\n  // Active-student count this dojo must reach before the milestone-gated\n  // features (certificates, announcements, transfers, invite-staff)\n  // auto-unlock. Defaults to 0 (features open immediately).\n  studentMilestone Int @default(0) @map(\"student_milestone\")\n\n  students        Student[]                @relation(\"DojoStudents\")\n  instructors     Instructor[]             @relation(\"DojoInstructors\")\n  managers        DojoManager[]            @relation(\"DojoManagers\")\n  owner           DojoOwner?               @relation(\"DojoOwner\")\n  application     DojoApplication?         @relation(\"DojoApplicationDojo\")\n  events          Event[]                  @relation(\"DojoEvents\")\n  announcements   Announcement[]           @relation(\"DojoAnnouncements\")\n  inventoryItems  DojoInventoryItem[]      @relation(\"DojoInventoryItems\")\n  sales           DojoSale[]               @relation(\"DojoSales\")\n  transfersOut    StudentTransferRequest[] @relation(\"TransferFromDojo\")\n  transfersIn     StudentTransferRequest[] @relation(\"TransferToDojo\")\n  historyFrom     StudentDojoHistory[]     @relation(\"HistoryFromDojo\")\n  historyTo       StudentDojoHistory[]     @relation(\"HistoryToDojo\")\n  serviceRequests ServiceRequest[]         @relation(\"ServiceRequestDojo\")\n  serviceCoupons  ServiceCoupon[]          @relation(\"ServiceCouponDojo\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"dojos\")\n}\n\n// ─────────────────────────────────────────────\n// DOJO ENLISTMENT APPLICATIONS\n// ─────────────────────────────────────────────\n\nenum DojoApplicationStatus {\n  PENDING_PAYMENT\n  PAID\n  APPROVED\n  REJECTED\n}\n\nmodel DojoApplication {\n  id     String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId String? @map(\"user_id\") @db.Uuid // Supabase auth.users id of the owner\n\n  dojoName    String    @map(\"dojo_name\")\n  logoUrl     String?   @map(\"logo_url\")\n  email       String\n  phone       String\n  contactName String    @map(\"contact_name\")\n  contactRole String    @map(\"contact_role\")\n  contactRank String?   @map(\"contact_rank\")\n  contactDob  DateTime? @map(\"contact_dob\") @db.Date\n\n  address   String\n  latitude  Float?\n  longitude Float?\n\n  interiorUrls String[] @default([]) @map(\"interior_urls\")\n  trainers     Json     @default(\"[]\")\n\n  status    DojoApplicationStatus @default(PENDING_PAYMENT)\n  paymentId String?               @map(\"payment_id\")\n\n  dojoId String? @unique @map(\"dojo_id\") @db.Uuid\n  dojo   Dojo?   @relation(\"DojoApplicationDojo\", fields: [dojoId], references: [id])\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"dojo_applications\")\n}\n\n// ─────────────────────────────────────────────\n// DOJO OWNER INVITES\n//\n// Admin-issued invitations to prospective Dojo Owners. The invite is a\n// promise sent by email — the invitee completes /enlist-dojo/signup on\n// their own; `acceptedAt` is stamped when a matching email finishes that\n// flow. Distinct from `dojo_applications`, which is the payload the\n// invitee submits.\n// ─────────────────────────────────────────────\n\nmodel DojoOwnerInvite {\n  id          String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  email       String    @unique\n  fullName    String?   @map(\"full_name\")\n  invitedById String    @map(\"invited_by_id\") @db.Uuid\n  invitedAt   DateTime  @default(now()) @map(\"invited_at\") @db.Timestamptz(6)\n  acceptedAt  DateTime? @map(\"accepted_at\") @db.Timestamptz(6)\n\n  invitedBy User @relation(\"DojoOwnerInvites\", fields: [invitedById], references: [id], onDelete: Cascade)\n\n  @@index([invitedById])\n  @@map(\"dojo_owner_invites\")\n}\n\n// ─────────────────────────────────────────────\n// GRADING EVENTS\n// ─────────────────────────────────────────────\n\nmodel GradingEvent {\n  id           String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name         String\n  eventDate    DateTime @map(\"event_date\") @db.Timestamptz(6)\n  location     String?\n  targetRankId String?  @map(\"target_rank_id\") @db.Uuid\n  isOpen       Boolean  @default(true) @map(\"is_open\")\n  notes        String?\n\n  cancelledAt  DateTime? @map(\"cancelled_at\") @db.Timestamptz(6)\n  cancelReason String?   @map(\"cancel_reason\")\n\n  resultsPublishedAt DateTime? @map(\"results_published_at\") @db.Timestamptz(6)\n\n  targetRank   BeltRank?            @relation(\"EventTargetRank\", fields: [targetRankId], references: [id])\n  gradings     Grading[]\n  applications GradingApplication[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"grading_events\")\n}\n\n// ─────────────────────────────────────────────\n// GRADING APPLICATIONS — students only\n// ─────────────────────────────────────────────\n\nmodel GradingApplication {\n  id             String            @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  studentId      String            @map(\"student_id\") @db.Uuid\n  gradingEventId String?           @map(\"grading_event_id\") @db.Uuid\n  targetRankId   String?           @map(\"target_rank_id\") @db.Uuid\n  status         ApplicationStatus @default(SUBMITTED)\n  notes          String?\n  declineReason  String?           @map(\"decline_reason\")\n  appliedAt      DateTime          @default(now()) @map(\"applied_at\") @db.Timestamptz(6)\n\n  student      Student       @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  gradingEvent GradingEvent? @relation(fields: [gradingEventId], references: [id], onDelete: Cascade)\n  targetRank   BeltRank?     @relation(\"AppTargetRank\", fields: [targetRankId], references: [id])\n\n  @@index([studentId])\n  @@index([gradingEventId])\n  @@map(\"grading_applications\")\n}\n\n// ─────────────────────────────────────────────\n// GRADINGS — students only\n// ─────────────────────────────────────────────\n\nmodel Grading {\n  id             String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  studentId      String        @map(\"student_id\") @db.Uuid\n  gradingEventId String?       @map(\"grading_event_id\") @db.Uuid\n  fromRankId     String?       @map(\"from_rank_id\") @db.Uuid\n  toRankId       String?       @map(\"to_rank_id\") @db.Uuid\n  result         GradingResult @default(PASSED)\n  marks          Int?          @db.SmallInt\n  certificateUrl String?       @map(\"certificate_url\")\n  notes          String?\n\n  /// True when marks >= 80 promoted the student two ranks instead of one.\n  /// See lib/grading-promotion.ts — toRankId already holds the final rank.\n  isDoublePromotion Boolean @default(false) @map(\"is_double_promotion\")\n\n  /// Post-publish pipeline stage. Only PASSED rows are meant to advance.\n  pipelineStage     GradingPipelineStage @default(QUALIFIED) @map(\"pipeline_stage\")\n  verifiedAt        DateTime?            @map(\"verified_at\") @db.Timestamptz(6)\n  verifiedByUserId  String?              @map(\"verified_by_user_id\") @db.Uuid\n  submittedAt       DateTime?            @map(\"submitted_at\") @db.Timestamptz(6)\n  submittedByUserId String?              @map(\"submitted_by_user_id\") @db.Uuid\n\n  student      Student       @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  gradingEvent GradingEvent? @relation(fields: [gradingEventId], references: [id])\n  fromRank     BeltRank?     @relation(\"GradingFromRank\", fields: [fromRankId], references: [id])\n  toRank       BeltRank?     @relation(\"GradingToRank\", fields: [toRankId], references: [id])\n\n  certificateRequests CertificateRequest[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"gradings\")\n}\n\n// ─────────────────────────────────────────────\n// CERTIFICATE REQUESTS — issued for students\n// ─────────────────────────────────────────────\n\nmodel CertificateRequest {\n  id             String                   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  gradingId      String                   @map(\"grading_id\") @db.Uuid\n  studentId      String                   @map(\"student_id\") @db.Uuid\n  dojoId         String                   @map(\"dojo_id\") @db.Uuid\n  orderId        String?                  @map(\"order_id\") @db.Uuid\n  status         CertificateRequestStatus @default(PENDING_PAYMENT)\n  price          Decimal                  @db.Decimal(10, 2)\n  certificateUrl String?                  @map(\"certificate_url\")\n  failureReason  String?                  @map(\"failure_reason\")\n\n  memberName String  @map(\"member_name\")\n  fatherName String? @map(\"father_name\")\n  motherName String? @map(\"mother_name\")\n  rankName   String  @map(\"rank_name\")\n\n  grading Grading    @relation(fields: [gradingId], references: [id], onDelete: Cascade)\n  student Student    @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  dojo    Dojo       @relation(fields: [dojoId], references: [id])\n  order   ShopOrder? @relation(\"OrderCertificates\", fields: [orderId], references: [id])\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([gradingId])\n  @@index([dojoId])\n  @@index([orderId])\n  @@index([status])\n  @@map(\"certificate_requests\")\n}\n\n// ─────────────────────────────────────────────\n// SYSTEM SETTINGS — singleton\n// ─────────────────────────────────────────────\n\nmodel SystemSettings {\n  id                 String  @id @default(\"default\")\n  adminSignatureUrl  String? @map(\"admin_signature_url\")\n  adminSignerName    String? @map(\"admin_signer_name\")\n  adminSignerTitle   String? @map(\"admin_signer_title\")\n  certificateLogoUrl String? @map(\"certificate_logo_url\")\n\n  // Subscription / affiliation fees (BDT). Editable from the admin\n  // subscriptions page; NULL means \"fall back to the built-in default\".\n  dojoEnlistmentFeeBDT  Decimal? @map(\"dojo_enlistment_fee_bdt\") @db.Decimal(10, 2)\n  dojoRenewalFeeBDT     Decimal? @map(\"dojo_renewal_fee_bdt\") @db.Decimal(10, 2)\n  membershipFeeBDT      Decimal? @map(\"membership_fee_bdt\") @db.Decimal(10, 2)\n  transferFeeBDT        Decimal? @map(\"transfer_fee_bdt\") @db.Decimal(10, 2)\n  pastBeltFeePerRankBDT Decimal? @map(\"past_belt_fee_per_rank_bdt\") @db.Decimal(10, 2)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"system_settings\")\n}\n\n// ─────────────────────────────────────────────\n// EVENTS — posted by any user (admin or dojo owner)\n// ─────────────────────────────────────────────\n\nmodel Event {\n  id          String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  title       String\n  description String?\n  eventDate   DateTime      @map(\"event_date\") @db.Timestamptz(6)\n  location    String?\n  imageUrl    String?       @map(\"image_url\")\n  isPublished Boolean       @default(false) @map(\"is_published\")\n  maxCapacity Int?          @map(\"max_capacity\")\n  category    EventCategory @default(OTHER)\n\n  attachmentUrl  String?         @map(\"attachment_url\")\n  attachmentType AttachmentType? @map(\"attachment_type\")\n\n  // Premium ticketing — ticketPrice is required (BDT) when isPremium is true.\n  isPremium   Boolean  @default(false) @map(\"is_premium\")\n  ticketPrice Decimal? @map(\"ticket_price\") @db.Decimal(10, 2)\n\n  // Discount percentage (0–100, 2dp) applied to the ticket price for\n  // signed-in JKA members with an ACTIVE membership. Zero = no discount.\n  memberDiscountPercent Decimal @default(0) @map(\"member_discount_percent\") @db.Decimal(5, 2)\n\n  // Optional discount applied when a participant selects 2 or more\n  // divisions in this event. `multiDivisionDiscountType` = \"PERCENT\" reads\n  // the value as a 0–100 percentage; \"FIXED\" reads it as a flat BDT\n  // amount subtracted from the division subtotal. Zero value = no\n  // multi-division discount regardless of type.\n  multiDivisionDiscountType    String  @default(\"PERCENT\") @map(\"multi_division_discount_type\")\n  multiDivisionDiscountPercent Decimal @default(0) @map(\"multi_division_discount_percent\") @db.Decimal(10, 2)\n\n  // Optional participation gates.\n  minAge          Int?                 @map(\"min_age\")\n  minRankId       String?              @map(\"min_rank_id\") @db.Uuid\n  participantType EventParticipantType @default(PUBLIC) @map(\"participant_type\")\n\n  postedById String? @map(\"posted_by_id\") @db.Uuid\n  dojoId     String? @map(\"dojo_id\") @db.Uuid\n\n  registrations    EventRegistration[]\n  postedBy         User?               @relation(\"EventsPosted\", fields: [postedById], references: [id])\n  dojo             Dojo?               @relation(\"DojoEvents\", fields: [dojoId], references: [id])\n  minRank          BeltRank?           @relation(\"EventMinRank\", fields: [minRankId], references: [id], onDelete: SetNull)\n  tournamentDetail TournamentDetail?\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([isPublished, eventDate])\n  @@index([category])\n  @@map(\"events\")\n}\n\n// ─────────────────────────────────────────────\n// TOURNAMENT DETAIL — 1:1 with Event when category = TOURNAMENT\n// ─────────────────────────────────────────────\n// Kata vs Kumite is set here, along with the subset of WKF divisions the\n// admin has enabled for this specific tournament. Division codes live in\n// lib/tournaments/divisions.ts — they are stable identifiers, not FKs.\n\nmodel TournamentDetail {\n  eventId              String                @id @map(\"event_id\") @db.Uuid\n  // Legacy single-type flag — kept for older rows and reporting. New writes\n  // also populate `enabledTypes`, and the participant flow reads from that.\n  eventType            TournamentEventType   @map(\"event_type\")\n  // 1 or 2 of KATA/KUMITE. An event may run both types.\n  enabledTypes         TournamentEventType[] @map(\"enabled_types\")\n  enabledDivisions     String[]              @map(\"enabled_divisions\")\n  // Admin-added categories not in the WKF preset. Shape:\n  //   { code: string, label: string, eventType: 'KATA'|'KUMITE', isTeam: boolean }[]\n  customDivisions      Json?                 @map(\"custom_divisions\")\n  registrationDeadline DateTime?             @map(\"registration_deadline\") @db.Timestamptz(6)\n  weighInDate          DateTime?             @map(\"weigh_in_date\") // KUMITE only @db.Timestamptz(6)\n  rulesUrl             String?               @map(\"rules_url\")\n\n  event Event @relation(fields: [eventId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"tournament_details\")\n}\n\n// ─────────────────────────────────────────────\n// ANNOUNCEMENTS — posted by any user\n// ─────────────────────────────────────────────\n\nmodel Announcement {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  title       String\n  body        String?\n  link        String?\n  isPublished Boolean  @default(true) @map(\"is_published\")\n  publishedAt DateTime @default(now()) @map(\"published_at\") @db.Timestamptz(6)\n\n  attachmentUrl  String?         @map(\"attachment_url\")\n  attachmentType AttachmentType? @map(\"attachment_type\")\n\n  postedById String? @map(\"posted_by_id\") @db.Uuid\n  dojoId     String? @map(\"dojo_id\") @db.Uuid\n\n  postedBy User? @relation(\"AnnouncementsPosted\", fields: [postedById], references: [id])\n  dojo     Dojo? @relation(\"DojoAnnouncements\", fields: [dojoId], references: [id])\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([isPublished, publishedAt])\n  @@map(\"announcements\")\n}\n\n// ─────────────────────────────────────────────\n// DIVISION PRESETS — reusable event division templates\n// ─────────────────────────────────────────────\n// Admins save the current form's divisions block (name + gates + fees) as\n// a preset they can import back into future event forms. `divisions` is\n// the same shape as TournamentDetail.customDivisions (see\n// lib/tournaments/divisions.ts).\n\nmodel DivisionPreset {\n  id          String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name        String\n  description String?\n  divisions   Json\n\n  createdById String? @map(\"created_by_id\") @db.Uuid\n  createdBy   User?   @relation(\"DivisionPresetsCreated\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([createdById, createdAt])\n  @@map(\"division_presets\")\n}\n\n// ─────────────────────────────────────────────\n// EVENT REGISTRATIONS — any user, or guest\n// ─────────────────────────────────────────────\n\nmodel EventRegistration {\n  id      String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  eventId String @map(\"event_id\") @db.Uuid\n\n  userId     String? @map(\"user_id\") @db.Uuid\n  guestName  String? @map(\"guest_name\")\n  guestEmail String? @map(\"guest_email\")\n  guestPhone String? @map(\"guest_phone\")\n\n  qrToken String @unique @map(\"qr_token\")\n\n  // Premium-event ticket payment. Null on free events; PENDING until the\n  // SSLCommerz payment settles, then PAID.\n  paymentStatus  PaymentStatus? @map(\"payment_status\")\n  // When a tournament participant pays for multiple divisions in one submit,\n  // every row in the group shares this id. The gateway session runs on the\n  // primary row's id + summed amount; markRegistrationPaid fans PAID out to\n  // the siblings.\n  paymentGroupId String?        @map(\"payment_group_id\") @db.Uuid\n  amountDue      Decimal?       @map(\"amount_due\") @db.Decimal(10, 2)\n  paidAt         DateTime?      @map(\"paid_at\") @db.Timestamptz(6)\n  transactionId  String?        @map(\"transaction_id\")\n\n  // Gate answers collected at registration time.\n  guestDateOfBirth     DateTime? @map(\"guest_date_of_birth\") @db.Date\n  parentOfMemberNumber String?   @map(\"parent_of_member_number\")\n\n  // ── Tournament-only fields (null on non-tournament events) ─────────────\n  // divisionCode references lib/tournaments/divisions.ts. gender + weight\n  // are captured on the registration row (rather than the profile) because\n  // weight in particular varies over time and is measured at weigh-in.\n  divisionCode    String?  @map(\"division_code\")\n  entrantGender   Gender?  @map(\"entrant_gender\")\n  entrantWeightKg Decimal? @map(\"entrant_weight_kg\") @db.Decimal(5, 2)\n  entrantBeltRank String?  @map(\"entrant_belt_rank\")\n  entrantDojoName String?  @map(\"entrant_dojo_name\") // free-text for guests\n  coachName       String?  @map(\"coach_name\")\n\n  // Team kata — teammates stored as JSON array of { name, memberNumber? }.\n  teamName  String? @map(\"team_name\")\n  teammates Json?   @map(\"teammates\")\n\n  // Minor guardian block — required when entrant is under 18 on event date.\n  guardianName    String?  @map(\"guardian_name\")\n  guardianPhone   String?  @map(\"guardian_phone\")\n  guardianConsent Boolean? @map(\"guardian_consent\")\n\n  emergencyContactName  String? @map(\"emergency_contact_name\")\n  emergencyContactPhone String? @map(\"emergency_contact_phone\")\n\n  // Optional profile image the participant uploaded — shown on their\n  // participation card. Cloudinary URL.\n  profileImageUrl String? @map(\"profile_image_url\")\n\n  // Snapshot of opt-in fees the entrant picked for THIS division row:\n  // [{ id, label, amountBdt }]. Snapshotting labels/amounts avoids drift\n  // if the admin later renames or reprices a fee.\n  selectedOptionalFees Json? @map(\"selected_optional_fees\")\n\n  checkedInAt       DateTime? @map(\"checked_in_at\") @db.Timestamptz(6)\n  checkedInByUserId String?   @map(\"checked_in_by_user_id\") @db.Uuid\n\n  event        Event                @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  user         User?                @relation(fields: [userId], references: [id], onDelete: Cascade)\n  checkedInBy  User?                @relation(\"EventCheckIns\", fields: [checkedInByUserId], references: [id])\n  transactions PaymentTransaction[] @relation(\"EventRegistrationTransactions\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  @@index([eventId, checkedInAt])\n  @@index([eventId, divisionCode])\n  @@map(\"event_registrations\")\n}\n\n// ─────────────────────────────────────────────\n// NOTIFICATIONS — any user\n// ─────────────────────────────────────────────\n\nmodel Notification {\n  id      String           @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId  String           @map(\"user_id\") @db.Uuid\n  title   String\n  message String\n  type    NotificationType @default(INFO)\n  isRead  Boolean          @default(false) @map(\"is_read\")\n  link    String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"notifications\")\n}\n\n// ─────────────────────────────────────────────\n// SHOP PRODUCTS\n// ─────────────────────────────────────────────\n\nmodel ShopProduct {\n  id          String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name        String\n  description String?\n  price       Decimal @db.Decimal(10, 2)\n  stock       Int     @default(0)\n  imageUrl    String? @map(\"image_url\")\n  category    String?\n  isActive    Boolean @default(true) @map(\"is_active\")\n\n  // Sizing — when hasSizes is true, customers must pick one of `sizes` before\n  // adding to cart. Kept as a plain text array so admins can use any labels\n  // (S/M/L, 32/34/36, kids/adult, etc.).\n  hasSizes Boolean  @default(false) @map(\"has_sizes\")\n  sizes    String[] @default([])\n\n  // Discount percentage (0–100) applied to signed-in JKA members with an\n  // ACTIVE membership. Zero = no discount.\n  memberDiscountPercent Int @default(0) @map(\"member_discount_percent\")\n\n  orderItems    ShopOrderItem[]\n  dojoInventory DojoInventoryItem[] @relation(\"InventoryProduct\")\n  dojoSaleItems DojoSaleItem[]      @relation(\"SaleItemProduct\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"shop_products\")\n}\n\n// ─────────────────────────────────────────────\n// DOJO INVENTORY\n// ─────────────────────────────────────────────\n\nmodel DojoInventoryItem {\n  id             String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  dojoId         String  @map(\"dojo_id\") @db.Uuid\n  productId      String  @map(\"product_id\") @db.Uuid\n  quantityOnHand Int     @default(0) @map(\"quantity_on_hand\")\n  unitPrice      Decimal @map(\"unit_price\") @db.Decimal(10, 2)\n\n  dojo    Dojo        @relation(\"DojoInventoryItems\", fields: [dojoId], references: [id], onDelete: Cascade)\n  product ShopProduct @relation(\"InventoryProduct\", fields: [productId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@unique([dojoId, productId])\n  @@index([dojoId])\n  @@map(\"dojo_inventory_items\")\n}\n\n// ─────────────────────────────────────────────\n// DOJO SALES (member receipts)\n// ─────────────────────────────────────────────\n\nmodel DojoSale {\n  id            String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  dojoId        String  @map(\"dojo_id\") @db.Uuid\n  receiptNo     String  @map(\"receipt_no\")\n  buyerUserId   String? @map(\"buyer_user_id\") @db.Uuid\n  buyerName     String  @map(\"buyer_name\")\n  soldByUserId  String? @map(\"sold_by_user_id\") @db.Uuid\n  soldByName    String? @map(\"sold_by_name\")\n  subtotal      Decimal @db.Decimal(10, 2)\n  discount      Decimal @default(0) @db.Decimal(10, 2)\n  total         Decimal @db.Decimal(10, 2)\n  paymentMethod String? @map(\"payment_method\")\n  notes         String?\n\n  dojo   Dojo           @relation(\"DojoSales\", fields: [dojoId], references: [id], onDelete: Cascade)\n  buyer  User?          @relation(\"DojoSaleBuyer\", fields: [buyerUserId], references: [id], onDelete: SetNull)\n  soldBy User?          @relation(\"DojoSaleSeller\", fields: [soldByUserId], references: [id], onDelete: SetNull)\n  items  DojoSaleItem[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  @@unique([dojoId, receiptNo])\n  @@index([dojoId, createdAt])\n  @@index([buyerUserId])\n  @@map(\"dojo_sales\")\n}\n\nmodel DojoSaleItem {\n  id          String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  saleId      String  @map(\"sale_id\") @db.Uuid\n  productId   String  @map(\"product_id\") @db.Uuid\n  productName String  @map(\"product_name\")\n  quantity    Int\n  unitPrice   Decimal @map(\"unit_price\") @db.Decimal(10, 2)\n  lineTotal   Decimal @map(\"line_total\") @db.Decimal(10, 2)\n\n  sale    DojoSale    @relation(fields: [saleId], references: [id], onDelete: Cascade)\n  product ShopProduct @relation(\"SaleItemProduct\", fields: [productId], references: [id])\n\n  @@index([saleId])\n  @@map(\"dojo_sale_items\")\n}\n\n// ─────────────────────────────────────────────\n// SHOP ORDERS — any user\n// ─────────────────────────────────────────────\n\nmodel ShopOrder {\n  id                 String                @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  userId             String?               @map(\"user_id\") @db.Uuid\n  paymentStatus      PaymentStatus         @default(PENDING) @map(\"payment_status\")\n  paymentMethod      String?               @map(\"payment_method\")\n  total              Decimal               @db.Decimal(10, 2)\n  currency           String                @default(\"BDT\")\n  transactionId      String?               @unique @map(\"transaction_id\")\n  includesMembership Boolean               @default(false) @map(\"includes_membership\")\n  membershipFee      Decimal?              @map(\"membership_fee\") @db.Decimal(10, 2)\n  fulfillmentStatus  ShopFulfillmentStatus @default(PREPARING) @map(\"fulfillment_status\")\n  notes              String?\n\n  // Guest shop-checkout fields — used when there is no logged-in user.\n  guestName    String? @map(\"guest_name\")\n  guestEmail   String? @map(\"guest_email\")\n  guestPhone   String? @map(\"guest_phone\")\n  guestAddress String? @map(\"guest_address\")\n  isGuestOrder Boolean @default(false) @map(\"is_guest_order\")\n\n  dojoId              String? @map(\"dojo_id\") @db.Uuid\n  includesDojoRenewal Boolean @default(false) @map(\"includes_dojo_renewal\")\n\n  includesCertificates Boolean @default(false) @map(\"includes_certificates\")\n  certDojoId           String? @map(\"cert_dojo_id\") @db.Uuid\n\n  includesTransferRequest Boolean @default(false) @map(\"includes_transfer_request\")\n\n  // Past-belt catch-up fee paid when a new student is accepted at a rank\n  // above White Belt. Consumed by the joining flow — see JoinStage.\n  includesPastBeltFee Boolean @default(false) @map(\"includes_past_belt_fee\")\n\n  // Generic service request (Kyu/Dan Conversion, admin-added services).\n  includesServiceRequest Boolean @default(false) @map(\"includes_service_request\")\n\n  user                User?                   @relation(fields: [userId], references: [id], onDelete: SetNull)\n  dojo                Dojo?                   @relation(\"DojoRenewalOrders\", fields: [dojoId], references: [id])\n  certDojo            Dojo?                   @relation(\"DojoCertificateOrders\", fields: [certDojoId], references: [id])\n  orderItems          ShopOrderItem[]\n  certificateRequests CertificateRequest[]    @relation(\"OrderCertificates\")\n  transferRequest     StudentTransferRequest? @relation(\"TransferOrder\")\n  serviceRequest      ServiceRequest?         @relation(\"ServiceRequestOrder\")\n  transactions        PaymentTransaction[]    @relation(\"OrderTransactions\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"shop_orders\")\n}\n\n// ─────────────────────────────────────────────\n// SHOP ORDER ITEMS\n// ─────────────────────────────────────────────\n\nmodel ShopOrderItem {\n  id        String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  orderId   String  @map(\"order_id\") @db.Uuid\n  productId String  @map(\"product_id\") @db.Uuid\n  quantity  Int\n  unitPrice Decimal @map(\"unit_price\") @db.Decimal(10, 2)\n  size      String?\n\n  order   ShopOrder   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product ShopProduct @relation(fields: [productId], references: [id])\n\n  @@map(\"shop_order_items\")\n}\n\n// ─────────────────────────────────────────────\n// TOURNAMENTS\n// ─────────────────────────────────────────────\n\nmodel Tournament {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name        String\n  description String?\n  date        DateTime @db.Timestamptz(6)\n  location    String?\n  isPublished Boolean  @default(false) @map(\"is_published\")\n\n  participants TournamentParticipant[]\n  matches      TournamentMatch[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"tournaments\")\n}\n\n// ─────────────────────────────────────────────\n// TOURNAMENT PARTICIPANTS — any user (students, admins-as-competitors)\n// ─────────────────────────────────────────────\n\nmodel TournamentParticipant {\n  id           String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tournamentId String  @map(\"tournament_id\") @db.Uuid\n  userId       String  @map(\"user_id\") @db.Uuid\n  category     String?\n  weightClass  String? @map(\"weight_class\")\n\n  tournament Tournament @relation(fields: [tournamentId], references: [id], onDelete: Cascade)\n  user       User       @relation(\"TournamentEntries\", fields: [userId], references: [id], onDelete: Cascade)\n\n  matchesAsP1 TournamentMatch[] @relation(\"MatchParticipant1\")\n  matchesAsP2 TournamentMatch[] @relation(\"MatchParticipant2\")\n  matchesWon  TournamentMatch[] @relation(\"MatchWinner\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  @@unique([tournamentId, userId])\n  @@map(\"tournament_participants\")\n}\n\n// ─────────────────────────────────────────────\n// TOURNAMENT MATCHES\n// ─────────────────────────────────────────────\n\nmodel TournamentMatch {\n  id             String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tournamentId   String  @map(\"tournament_id\") @db.Uuid\n  participant1Id String? @map(\"participant1_id\") @db.Uuid\n  participant2Id String? @map(\"participant2_id\") @db.Uuid\n  winnerId       String? @map(\"winner_id\") @db.Uuid\n  round          Int?\n  matchOrder     Int?    @map(\"match_order\")\n  notes          String?\n\n  tournament   Tournament             @relation(fields: [tournamentId], references: [id], onDelete: Cascade)\n  participant1 TournamentParticipant? @relation(\"MatchParticipant1\", fields: [participant1Id], references: [id])\n  participant2 TournamentParticipant? @relation(\"MatchParticipant2\", fields: [participant2Id], references: [id])\n  winner       TournamentParticipant? @relation(\"MatchWinner\", fields: [winnerId], references: [id])\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  @@map(\"tournament_matches\")\n}\n\n// ─────────────────────────────────────────────\n// ACHIEVEMENTS\n// ─────────────────────────────────────────────\n\nmodel Achievement {\n  id            String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  slug          String          @unique\n  name          String\n  nameBn        String?         @map(\"name_bn\")\n  description   String\n  descriptionBn String?         @map(\"description_bn\")\n  icon          String\n  tier          AchievementTier @default(COMMON)\n  rule          AchievementRule @default(MANUAL)\n  threshold     Int?\n  orderIndex    Int             @default(0) @map(\"order_index\")\n  isActive      Boolean         @default(true) @map(\"is_active\")\n\n  studentAchievements StudentAchievement[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([tier, orderIndex])\n  @@map(\"achievements\")\n}\n\nmodel StudentAchievement {\n  id              String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  studentId       String   @map(\"student_id\") @db.Uuid\n  achievementId   String   @map(\"achievement_id\") @db.Uuid\n  unlockedAt      DateTime @default(now()) @map(\"unlocked_at\") @db.Timestamptz(6)\n  progress        Int      @default(0)\n  awardedByUserId String?  @map(\"awarded_by_user_id\") @db.Uuid\n  note            String?\n\n  student     Student     @relation(\"StudentAchievements\", fields: [studentId], references: [id], onDelete: Cascade)\n  achievement Achievement @relation(fields: [achievementId], references: [id], onDelete: Cascade)\n  awardedBy   User?       @relation(\"StudentAchievementsAwarded\", fields: [awardedByUserId], references: [id], onDelete: SetNull)\n\n  @@unique([studentId, achievementId])\n  @@index([studentId])\n  @@index([achievementId])\n  @@map(\"student_achievements\")\n}\n\n// ─────────────────────────────────────────────\n// STUDENT DOJO TRANSFER REQUESTS\n// ─────────────────────────────────────────────\n\nmodel StudentTransferRequest {\n  id         String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  studentId  String @map(\"student_id\") @db.Uuid\n  fromDojoId String @map(\"from_dojo_id\") @db.Uuid\n  toDojoId   String @map(\"to_dojo_id\") @db.Uuid\n\n  status       StudentTransferStatus       @default(PENDING_PAYMENT)\n  dojoDecision StudentTransferDojoDecision @default(PENDING) @map(\"dojo_decision\")\n\n  reason    String?\n  dojoNote  String? @map(\"dojo_note\")\n  adminNote String? @map(\"admin_note\")\n\n  fee            Decimal  @db.Decimal(10, 2)\n  discountAmount Decimal  @default(0) @map(\"discount_amount\") @db.Decimal(10, 2)\n  finalAmount    Decimal? @map(\"final_amount\") @db.Decimal(10, 2)\n  couponCode     String?  @map(\"coupon_code\")\n\n  orderId String? @unique @map(\"order_id\") @db.Uuid\n\n  paidAt           DateTime? @map(\"paid_at\") @db.Timestamptz(6)\n  dojoActedAt      DateTime? @map(\"dojo_acted_at\") @db.Timestamptz(6)\n  dojoActedById    String?   @map(\"dojo_acted_by_id\") @db.Uuid\n  adminActedAt     DateTime? @map(\"admin_acted_at\") @db.Timestamptz(6)\n  adminActedById   String?   @map(\"admin_acted_by_id\") @db.Uuid\n  newDojoActedAt   DateTime? @map(\"new_dojo_acted_at\") @db.Timestamptz(6)\n  newDojoActedById String?   @map(\"new_dojo_acted_by_id\") @db.Uuid\n  assignedRank     String?   @map(\"assigned_rank\")\n\n  student        Student    @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  fromDojo       Dojo       @relation(\"TransferFromDojo\", fields: [fromDojoId], references: [id])\n  toDojo         Dojo       @relation(\"TransferToDojo\", fields: [toDojoId], references: [id])\n  order          ShopOrder? @relation(\"TransferOrder\", fields: [orderId], references: [id], onDelete: SetNull)\n  dojoActedBy    User?      @relation(\"TransferDojoActor\", fields: [dojoActedById], references: [id], onDelete: SetNull)\n  adminActedBy   User?      @relation(\"TransferAdminActor\", fields: [adminActedById], references: [id], onDelete: SetNull)\n  newDojoActedBy User?      @relation(\"TransferNewDojoActor\", fields: [newDojoActedById], references: [id], onDelete: SetNull)\n\n  history StudentDojoHistory[] @relation(\"HistoryTransferRequest\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([studentId])\n  @@index([fromDojoId, status])\n  @@index([toDojoId, status])\n  @@index([status])\n  @@map(\"student_transfer_requests\")\n}\n\n// ─────────────────────────────────────────────\n// STUDENT DOJO HISTORY  — audit log of dojo changes\n// ─────────────────────────────────────────────\n\n// ─────────────────────────────────────────────\n// PAYMENT TRANSACTIONS — audit log for every gateway attempt\n// ─────────────────────────────────────────────\n\nmodel PaymentTransaction {\n  id String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n\n  // Linked domain rows. ShopOrder covers membership / past-belt / cert /\n  // dojo-renewal / transfer / shop paths; eventRegistrationId covers event\n  // tickets which have their own domain object.\n  orderId             String? @map(\"order_id\") @db.Uuid\n  eventRegistrationId String? @map(\"event_registration_id\") @db.Uuid\n  userId              String? @map(\"user_id\") @db.Uuid\n\n  provider     PaymentProvider          @default(SSLCOMMERZ)\n  kind         PaymentTransactionKind\n  status       PaymentTransactionStatus @default(PENDING)\n  amount       Decimal                  @db.Decimal(10, 2)\n  currency     String                   @default(\"BDT\")\n  gatewayTxnId String?                  @map(\"gateway_txn_id\")\n  reason       String?\n  buyerName    String?                  @map(\"buyer_name\")\n  buyerEmail   String?                  @map(\"buyer_email\")\n  buyerPhone   String?                  @map(\"buyer_phone\")\n\n  order             ShopOrder?         @relation(\"OrderTransactions\", fields: [orderId], references: [id], onDelete: SetNull)\n  eventRegistration EventRegistration? @relation(\"EventRegistrationTransactions\", fields: [eventRegistrationId], references: [id], onDelete: SetNull)\n  user              User?              @relation(\"UserTransactions\", fields: [userId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([orderId])\n  @@index([eventRegistrationId])\n  @@index([userId])\n  @@index([status])\n  @@index([kind])\n  @@index([createdAt])\n  @@map(\"payment_transactions\")\n}\n\nmodel StudentDojoHistory {\n  id                String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  studentId         String  @map(\"student_id\") @db.Uuid\n  fromDojoId        String? @map(\"from_dojo_id\") @db.Uuid\n  toDojoId          String? @map(\"to_dojo_id\") @db.Uuid\n  transferRequestId String? @map(\"transfer_request_id\") @db.Uuid\n  changedById       String? @map(\"changed_by_id\") @db.Uuid\n  reason            String?\n\n  student         Student                 @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  fromDojo        Dojo?                   @relation(\"HistoryFromDojo\", fields: [fromDojoId], references: [id])\n  toDojo          Dojo?                   @relation(\"HistoryToDojo\", fields: [toDojoId], references: [id])\n  transferRequest StudentTransferRequest? @relation(\"HistoryTransferRequest\", fields: [transferRequestId], references: [id], onDelete: SetNull)\n  changedBy       User?                   @relation(\"HistoryChangedBy\", fields: [changedById], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  @@index([studentId])\n  @@map(\"student_dojo_history\")\n}\n\n// ─────────────────────────────────────────────\n// SERVICES CATALOG — admin-managed list of purchasable services\n// ─────────────────────────────────────────────\n\nmodel Service {\n  id          String  @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  slug        String  @unique\n  name        String\n  description String?\n  feeBDT      Decimal @map(\"fee_bdt\") @db.Decimal(10, 2)\n  isActive    Boolean @default(true) @map(\"is_active\")\n\n  // Handler slug: which client flow to route to. \"kyu-dan-conversion\" and\n  // \"generic\" are recognized today; more can be added without a migration.\n  handler String @default(\"generic\")\n\n  requests ServiceRequest[]\n  coupons  ServiceCoupon[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"services\")\n}\n\n// ─────────────────────────────────────────────\n// SERVICE REQUESTS — student submits, dojo approves, admin approves\n// ─────────────────────────────────────────────\n\nmodel ServiceRequest {\n  id        String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  studentId String @map(\"student_id\") @db.Uuid\n  serviceId String @map(\"service_id\") @db.Uuid\n  dojoId    String @map(\"dojo_id\") @db.Uuid\n\n  status       ServiceRequestStatus       @default(PENDING_PAYMENT)\n  dojoDecision ServiceRequestDojoDecision @default(PENDING) @map(\"dojo_decision\")\n\n  // Free-form request payload (e.g. { requestedRank, currentRank } for\n  // kyu-dan conversion). Kept as JSON so admin-added services can carry\n  // their own fields without schema churn.\n  payload Json @default(\"{}\")\n\n  reason    String?\n  dojoNote  String? @map(\"dojo_note\")\n  adminNote String? @map(\"admin_note\")\n\n  fee            Decimal @db.Decimal(10, 2)\n  discountAmount Decimal @default(0) @map(\"discount_amount\") @db.Decimal(10, 2)\n  finalAmount    Decimal @map(\"final_amount\") @db.Decimal(10, 2)\n  couponId       String? @map(\"coupon_id\") @db.Uuid\n  couponCode     String? @map(\"coupon_code\")\n\n  orderId String? @unique @map(\"order_id\") @db.Uuid\n\n  paidAt         DateTime? @map(\"paid_at\") @db.Timestamptz(6)\n  dojoActedAt    DateTime? @map(\"dojo_acted_at\") @db.Timestamptz(6)\n  dojoActedById  String?   @map(\"dojo_acted_by_id\") @db.Uuid\n  adminActedAt   DateTime? @map(\"admin_acted_at\") @db.Timestamptz(6)\n  adminActedById String?   @map(\"admin_acted_by_id\") @db.Uuid\n\n  student      Student        @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  service      Service        @relation(fields: [serviceId], references: [id])\n  dojo         Dojo           @relation(\"ServiceRequestDojo\", fields: [dojoId], references: [id])\n  order        ShopOrder?     @relation(\"ServiceRequestOrder\", fields: [orderId], references: [id], onDelete: SetNull)\n  coupon       ServiceCoupon? @relation(fields: [couponId], references: [id], onDelete: SetNull)\n  dojoActedBy  User?          @relation(\"ServiceRequestDojoActor\", fields: [dojoActedById], references: [id], onDelete: SetNull)\n  adminActedBy User?          @relation(\"ServiceRequestAdminActor\", fields: [adminActedById], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([studentId])\n  @@index([dojoId, status])\n  @@index([serviceId, status])\n  @@index([status])\n  @@map(\"service_requests\")\n}\n\n// ─────────────────────────────────────────────\n// SERVICE COUPONS — issued by a dojo, redeemed at checkout\n// ─────────────────────────────────────────────\n\nmodel ServiceCoupon {\n  id              String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  code            String    @unique\n  dojoId          String    @map(\"dojo_id\") @db.Uuid\n  createdById     String    @map(\"created_by_id\") @db.Uuid\n  discountPercent Int       @map(\"discount_percent\") // 1-100\n  serviceId       String?   @map(\"service_id\") @db.Uuid // null = any service\n  usageLimit      Int       @default(1) @map(\"usage_limit\")\n  usedCount       Int       @default(0) @map(\"used_count\")\n  expiresAt       DateTime? @map(\"expires_at\") @db.Timestamptz(6)\n  isActive        Boolean   @default(true) @map(\"is_active\")\n  notes           String?\n\n  dojo      Dojo             @relation(\"ServiceCouponDojo\", fields: [dojoId], references: [id], onDelete: Cascade)\n  service   Service?         @relation(fields: [serviceId], references: [id], onDelete: SetNull)\n  createdBy User             @relation(\"ServiceCouponCreator\", fields: [createdById], references: [id], onDelete: Cascade)\n  requests  ServiceRequest[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([dojoId])\n  @@index([serviceId])\n  @@map(\"service_coupons\")\n}\n"
}

